def floor_log2(x):
    """largest L with 2**L <= x, for positive Fraction x"""
    n, d = x.numerator, x.denominator
    L = n.bit_length() - d.bit_length()
    while Fr(2) ** L > x:
        L -= 1
    while Fr(2) ** (L + 1) <= x:
        L += 1
    return L


def round_int(r, mode, sign):
    """round positive Fraction r to a non-negative integer"""
    n, d = r.numerator, r.denominator
    base, rem = divmod(n, d)
    if rem == 0:
        return base
    if mode == 'RTZ':
        return base
    if mode == 'RNE':
        c = 2 * rem - d
        if c > 0:
            return base + 1
        if c < 0:
            return base
